#include <cstdio>
using namespace std;

int n, m, x, s[100];

int main() {
    while (scanf("%d %d", &n, &m), n + m) {
        for (int i = 0; i < m; i++) scanf("%d", &s[i]);

        // Use a single pass to check if the final values remain non-negative
        bool f = true;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                scanf("%d", &x);
                s[j] -= x;
                if (s[j] < 0) f = false; // Check condition immediately
            }
            if (!f) break; // Break early if a negative is found
        }

        printf("%s\n", f ? "Yes" : "No");
    }
}

